import AppKit
import TeleSaveCore

/// "Send to TeleSave" in Finder's right-click menu, implemented as a macOS Service (Info.plist `NSServices`).
///
/// The menu title is localized by macOS from `<lang>.lproj/ServicesMenu.strings` (generated by the build
/// script from the translation files), so it follows the system language.
enum FinderService {
    /// Must match `NSMenuItem.default` and `NSMessage` in Config/Info.plist.
    static let menuTitle = "Send to TeleSave"
    static let message = "sendToTeleSave"

    /// Key macOS uses in the `pbs` preferences to remember whether a service is enabled.
    static var statusKey: String {
        "\(Bundle.main.bundleIdentifier ?? "com.telesave.app") - \(menuTitle) - \(message)"
    }

    /// Shows or hides the menu item, the same way System Settings › Keyboard › Services does.
    static func setEnabled(_ enabled: Bool) {
        let domain = "pbs" as CFString
        let key = "NSServicesStatus" as CFString
        var status = CFPreferencesCopyAppValue(key, domain) as? [String: Any] ?? [:]
        status[statusKey] = [
            "enabled_context_menu": enabled,
            "enabled_services_menu": enabled,
            "presentation_modes": ["ContextMenu": enabled, "ServicesMenu": enabled]
        ]
        CFPreferencesSetAppValue(key, status as CFDictionary, domain)
        CFPreferencesAppSynchronize(domain)
        NSUpdateDynamicServices()
    }
}

/// Receives the files when the user picks "Send to TeleSave".
@MainActor
final class FinderServiceProvider: NSObject {
    private weak var model: AppModel?

    init(model: AppModel) {
        self.model = model
    }

    @objc func sendToTeleSave(_ pasteboard: NSPasteboard, userData: String?, error: AutoreleasingUnsafeMutablePointer<NSString>) {
        guard let model, AppSettings.isAppStoreBuild || model.settings.finderServiceEnabled else { return }
        let urls = pasteboard.readObjects(forClasses: [NSURL.self], options: [.urlReadingFileURLsOnly: true]) as? [URL] ?? []
        guard !urls.isEmpty else {
            error.pointee = "No files" as NSString
            return
        }
        model.handleDrop(urls, fromStatusItem: true)
    }
}
